/*
 * IR Remote Decoder
 * Receives NEC IR codes from a remote control and prints them
 * to the Serial Monitor. The built-in LED (D13) blinks on each press.
 *
 * Wiring:
 *   TSOP4838 OUT → D2
 *   TSOP4838 VCC → 5V, GND → GND
 *   IR Remote — click any button on the canvas remote to send a code.
 */

#include <IRremote.h>

const int RECV_PIN = 2;
IRrecv irrecv(RECV_PIN);
decode_results results;

void setup() {
  Serial.begin(9600);
  irrecv.enableIRIn();
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.println("IR Remote Decoder ready");
  Serial.println("Press a button on the remote...");
}

void loop() {
  if (irrecv.decode(&results)) {
    Serial.print("Code: 0x");
    Serial.print(results.value, HEX);
    Serial.print("  Protocol: ");
    Serial.println(results.decode_type);

    digitalWrite(LED_BUILTIN, HIGH);
    delay(100);
    digitalWrite(LED_BUILTIN, LOW);

    irrecv.resume();
  }
}
